create or replace function public.claim_character_achievements(target_character_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare hero public.characters%rowtype;definition public.achievement_definitions%rowtype;progress integer;new_ids bigint[]:=array[]::bigint[];begin select*into hero from public.characters where id=target_character_id and user_id=auth.uid();if hero.id is null then raise exception'character not found';end if;for definition in select*from public.achievement_definitions where active order by sort_order loop progress:=case definition.condition_key when'character_created'then 1 when'travel_count'then(select count(*)from public.character_travel_history where character_id=hero.id)when'craft_count'then(select count(*)from public.cooking_history where character_id=hero.id)+(select count(*)from public.brewing_history where character_id=hero.id)when'quest_count'then(select count(*)from public.character_quests where character_id=hero.id and status='completed')when'forge_count'then(select count(*)from public.generated_items where character_id=hero.id)when'world_boss_hits'then(select count(*)from public.world_boss_contributions where character_id=hero.id)else 0 end;if progress>=definition.target_value then insert into public.character_achievements(character_id,user_id,achievement_id,progress_value)values(hero.id,hero.user_id,definition.id,progress)on conflict do nothing;if found then new_ids:=array_append(new_ids,definition.id);end if;end if;end loop;return jsonb_build_object('new_achievement_ids',to_jsonb(new_ids),'new_count',cardinality(new_ids));end;$$;
